CREATE INDEX IF NOT EXISTS idx_tenants_user_id ON tenants(user_id);
CREATE INDEX IF NOT EXISTS idx_tenants_property ON tenants(property_id);
CREATE INDEX IF NOT EXISTS idx_tenants_unit ON tenants(unit);
CREATE INDEX IF NOT EXISTS idx_tenants_status ON tenants(status);
CREATE INDEX IF NOT EXISTS idx_payments_tenant_id ON payments(tenant_id);
CREATE INDEX IF NOT EXISTS idx_payments_property ON payments(property_id);
CREATE INDEX IF NOT EXISTS idx_payments_status ON payments(status);
CREATE INDEX IF NOT EXISTS idx_payments_date ON payments(date);
CREATE INDEX IF NOT EXISTS idx_payments_reference ON payments(paystack_ref);
CREATE INDEX IF NOT EXISTS idx_tickets_tenant_id ON tickets(tenant_id);
CREATE INDEX IF NOT EXISTS idx_tickets_property ON tickets(property_id);
CREATE INDEX IF NOT EXISTS idx_tickets_status ON tickets(status);
CREATE INDEX IF NOT EXISTS idx_inbox_read ON inbox(read);
CREATE INDEX IF NOT EXISTS idx_activity_time ON activity(time DESC);
CREATE INDEX IF NOT EXISTS idx_files_tenant ON files(tenant_id);
CREATE INDEX IF NOT EXISTS idx_files_applicant ON files(applicant_id);
CREATE INDEX IF NOT EXISTS idx_notices_type ON notices(type);
CREATE INDEX IF NOT EXISTS idx_notices_sent ON notices(sent_at DESC);
CREATE INDEX IF NOT EXISTS idx_invitations_token ON invitations(token);
CREATE INDEX IF NOT EXISTS idx_invitations_phone ON invitations(phone);
CREATE INDEX IF NOT EXISTS idx_agreements_tenant ON agreements(tenant_id);
CREATE INDEX IF NOT EXISTS idx_agreements_status ON agreements(status);
CREATE INDEX IF NOT EXISTS idx_applicants_property ON applicants(property_id);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_logs(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_logs(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_email_queue_status ON email_queue(status);
-- ── SEED DATA ──────────────────────────────────────────────────────INSERT INTO units (property_id, name, type, occupied, status, monthly_rent, deposit_amount)SELECT (SELECT id FROM properties ORDER BY created_at ASC LIMIT 1), name, type, occupied,  CASE WHEN occupied THEN 'occupied' ELSE 'available' END,  CASE type    WHEN 'apartment' THEN 500000    WHEN 'shop' THEN 800000    WHEN 'stall' THEN 300000  END,  CASE type    WHEN 'apartment' THEN 50000    WHEN 'shop' THEN 80000    WHEN 'stall' THEN 30000  ENDFROM (  VALUES    ('Apt 1', 'apartment', true),    ('Apt 2', 'apartment', true),    ('Apt 3', 'apartment', true),    ('Apt 4', 'apartment', false),    ('Shop 1', 'shop', true),    ('Shop 2', 'shop', false),    ('Stall 1', 'stall', false),    ('Stall 2', 'stall', true)  ) AS seed(name, type, occupied)WHERE NOT EXISTS (SELECT 1 FROM units WHERE name = seed.name);
